16	namespace hybrid
17	{
18	
19	class StateDrain
20	{
21	public:
22	  using RD = ResumeDriver;
23	
24	  // scratch_gpa: the GUEST address of the V-register transport page (L26: the
25	  // mmap's top page, v_scratch_gpa(ram_base, ram_size)). Defaults to the unset
26	  // sentinel; only the V dump sweep consults it. The simulator passes the real
27	  // value from platform.main_memory.
28	  explicit StateDrain(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
29	                      AndesCaps caps = AndesCaps::all())
30	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
31	  {}
32	
33	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
34	  // drain_with_passthrough when the QEMU 1 snapshot is available.
35	  auto drain() -> hybrid_state_v1
36	  {
37	    hybrid_state_v1 state{};
38	    state.magic   = HYBRID_STATE_MAGIC;
39	    state.version = HYBRID_STATE_VERSION;
40	    state.flags   = HYBRID_FLAG_RV64;
41	    halt_and_capture_pc_priv(state);
42	
43	    for (uint16_t i = 1; i < 32; ++i)
44	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
45	
46	    return state;
47	  }
48	
49	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
50	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
51	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
52	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set,
53	  // also freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
54	  // and vreg remain pass-through (read-only / too large for DM). L23 mscratch
55	  // and the L24 trap/interrupt CSRs round-trip too (ResumeDriver restores
56	  // them). The Andes block and the M-ext CSRs round-trip too; only the L2C
57	  // re-read lands in a later commit.
58	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
59	  // contribution would otherwise be discarded as the passthrough preserves
60	  // QEMU1's pre-handoff value.
61	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
62	  {
63	    auto state = input;
64	    halt_and_capture_pc_priv(state);  // L6: pc + privilege at the exit halt
65	
66	    // GPRs/FPRs: one abstract register read each. Abstract-only by design,
67	    // like the resume side -- the Program Buffer is reserved for state the
68	    // abstract command space cannot reach (the V regfile, vtype+vl, the L2C
69	    // MMIO window).
70	    for (uint16_t i = 1; i < 32; ++i)
71	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
72	
73	    if (input.flags & HYBRID_FLAG_FP) {
74	      for (uint16_t i = 0; i < 32; ++i)
75	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
76	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
77	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
78	    }
79	
80	    if (input.flags & HYBRID_FLAG_V) {
81	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
82	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
83	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
84	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
85	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
86	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
87	    }
88	
89	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
90	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
91	    // dropped and the stale QEMU1 value passes through into the drained state.
92	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
93	
94	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
95	    // restores them), so re-read them -- an in-ROI write must reach the drained
96	    // state instead of the stale QEMU1 passthrough value.
97	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
98	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
99	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
100	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
101	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
102	
103	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
104	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
105	
106	    // Andes V5 + M-ext CSR block (v3/v4): re-read the transported CSRs so an
107	    // in-ROI write reaches the drained state instead of the stale QEMU1
108	    // passthrough (same round-trip as mscratch). One caps-gated abstract read
109	    // per CSR. See drain_andes_m_ext.
110	    drain_andes_m_ext(state);
111	
112	    // V data regfile: dump v0..v31 to the shared scratch region via the
113	    // Program Buffer LAST -- after every architectural read above -- so the
114	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
115	    // cannot corrupt the values already captured. The simulator's
116	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
117	    if (input.flags & HYBRID_FLAG_V)
118	      dump_v_to_scratch(input.vlenb);
119	
120	    return state;
121	  }
122	
123	private:
124	  // Andes V5 + M-ext CSR drain: one caps-gated abstract read per CSR into
125	  // state. Abstract-only by design, same caps gate + canonical order as the
126	  // ResumeDriver restore.
127	  void drain_andes_m_ext(hybrid_state_v1& state)
128	  {
129	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
130	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
131	    if (!andes && !mext) return;
132	
133	    if (andes) {
134	#define X(field, addr, name) \
135	  if (caps_.supports_csr(addr)) \
136	    state.andes.field = read_register_64(bus_, regno_csr(addr));
137	      HYBRID_ANDES_CSR_LIST(X)
138	#undef X
139	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
140	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
141	          state.andes.pmacfg[i] =
142	            read_register_64(bus_, regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
143	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
144	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
145	          state.andes.pmaaddr[i] =
146	            read_register_64(bus_, regno_csr(HYBRID_PMA_ADDR0_CSR + i));
147	    }
148	    if (mext) {
149	#define X(field, addr, name) \
150	  if (caps_.supports_csr(addr)) \
151	    state.m_ext.field = read_register_64(bus_, regno_csr(addr));
152	      HYBRID_M_EXT_CSR_LIST(X)
153	#undef X
154	    }
155	  }
156	
157	  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
158	  // L26: guards on the configured scratch GPA so a V drain never stores to a
159	  // bogus address (mirror of ResumeDriver's reload-sweep guard).
160	  void dump_v_to_scratch(uint64_t vlenb)
161	  {
162	    if (scratch_gpa_ == kVScratchGpaUnset)
163	      throw std::runtime_error(
164	        "StateDrain: V state present but scratch GPA unset");
165	    pb_v_data_sweep(bus_, scratch_gpa_, vlenb, /*load=*/false);
166	  }
167	
168	  // Halt the hart and capture the two control fields every drain path needs:
169	  // privilege (dcsr.prv, L6) and PC (dpc). dmactive must transition 0->1 in
170	  // its own write before haltreq is honored (RISC-V Debug Spec), then wait
171	  // for allhalted. Header fields and the register blocks are filled by the
172	  // caller.
173	  void halt_and_capture_pc_priv(hybrid_state_v1& state)
174	  {
175	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
176	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
177	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
178	                   "StateDrain halt");
179	
180	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
181	                                  "StateDrain DCSR") & 0x3u;
182	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
183	  }
184	
185	  DmiBus& bus_;
186	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
187	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
188	};
189	
190	}  // namespace hybrid
