462	// v4 M-ext completion: the whole HYBRID_M_EXT_CSR_LIST block round-trips through
463	// the drain, one caps-gated abstract read per CSR -- never a batched
464	// Program-Buffer csrr+sd sweep (which could not tolerate a mid-batch cmderr
465	// without corrupting the rest).
466	TEST_CASE("CSR drain is Abstract-Command-only: every Andes+M-ext CSR gets its "
467	          "own abstract read, never a Program-Buffer csrr+sd sweep")
468	{
469	  RecordingBus bus;
470	  bus.dmstatus_value   = kDmstatusHaltedAndAcked;
471	  bus.abstractcs_value = 8u << 24;  // progbufsize=8: a batch would fit here
472	
473	  hybrid_state_v1 input{};
474	  input.magic   = HYBRID_STATE_MAGIC;
475	  input.version = HYBRID_STATE_VERSION;
476	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;
477	  input.priv    = 3;
478	  input.vlenb   = 0;  // no V PB traffic: isolate the CSR drain path
479	
480	  // Preload the regfile so every transported CSR has a distinct value.
481	  std::vector<uint16_t> addrs;
482	  hybrid::for_each_transport_csr(input, hybrid::AndesCaps::all(),
483	    [&](uint16_t a, const uint64_t&) { addrs.push_back(a); });
484	  REQUIRE(!addrs.empty());
485	  for (std::size_t k = 0; k < addrs.size(); ++k)
486	    bus.regfile[hybrid::regno_csr(addrs[k])] = 0xC5000000ULL + k;
487	
488	  hybrid::StateDrain drain(bus, kScratch);
489	  auto state = drain.drain_with_passthrough(input);
490	
491	  // (a) every transported CSR's value landed in the state via its own
492	  //     abstract read.
493	  std::size_t k = 0;
494	  hybrid::for_each_transport_csr(state, hybrid::AndesCaps::all(),
495	    [&](uint16_t, uint64_t& field) {
496	      CHECK(field == 0xC5000000ULL + k);
497	      ++k;
498	    });
499	
500	  // (b) no Program-Buffer execution occurred at all -- with no V state and no
501	  //     L2C, the only possible PB user would have been a CSR sweep.
502	  for (const auto& op : bus.ops)
503	    CHECK_FALSE((op.kind == DmiOp::Kind::Write && op.reg == RD::kCommand
504	                 && op.value == hybrid::kExecProgbufCmd));
