544	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_V: V CSR reads issued after GPR reads")
545	{
546	  RecordingBus bus;
547	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
548	
549	  hybrid_state_v1 input{};
550	  input.magic   = HYBRID_STATE_MAGIC;
551	  input.version = HYBRID_STATE_VERSION;
552	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
553	  input.priv    = 3;
554	
555	  hybrid::StateDrain drain(bus, kScratch);
556	  (void) drain.drain_with_passthrough(input);
557	
558	  // Find the last GPR COMMAND read and the first V CSR COMMAND read.
559	  std::optional<std::size_t> last_gpr_cmd;
560	  std::optional<std::size_t> first_vcsr_cmd;
561	  const std::initializer_list<uint16_t> vcsr_regnos = {
562	    hybrid::regno_csr(RD::kCsrVstart),
563	    hybrid::regno_csr(RD::kCsrVxsat),
564	    hybrid::regno_csr(RD::kCsrVxrm),
565	    hybrid::regno_csr(RD::kCsrVcsr),
566	    hybrid::regno_csr(RD::kCsrVtype),
567	    hybrid::regno_csr(RD::kCsrVl),
568	  };
569	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
570	    const auto& op = bus.ops[i];
571	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
572	    const uint16_t regno = op.value & 0xFFFFu;
573	    // Only register READS matter here. The V-data dump sweep also issues GPR
574	    // WRITES (x5/x6/x7 scratch) at the end of drain; those are not the
575	    // architectural GPR reads this ordering check is about.
576	    const bool is_read = ((op.value >> 16) & 1u) == 0u;
577	    if (is_read && regno >= hybrid::regno_gpr(1) && regno <= hybrid::regno_gpr(31))
578	      last_gpr_cmd = i;
579	    for (uint16_t vcsr : vcsr_regnos)
580	      if (is_read && !first_vcsr_cmd && regno == vcsr)
581	        first_vcsr_cmd = i;
582	  }
583	  REQUIRE(last_gpr_cmd.has_value());
584	  REQUIRE(first_vcsr_cmd.has_value());
585	  CHECK(*last_gpr_cmd < *first_vcsr_cmd);
586	}
