637	TEST_CASE("drain_with_passthrough with HYBRID_FLAG_V: PB dumps v0..v31 to scratch "
638	          "after the architectural counter reads")
639	{
640	  RecordingBus bus;
641	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
642	
643	  hybrid_state_v1 input{};
644	  input.magic   = HYBRID_STATE_MAGIC;
645	  input.version = HYBRID_STATE_VERSION;
646	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_V;
647	  input.priv    = 3;
648	  input.vlenb   = 64;
649	
650	  hybrid::StateDrain drain(bus, kScratch);
651	  (void) drain.drain_with_passthrough(input);
652	
653	  // (a) all 32 registers are dumped as 4 LMUL=8 groups: one vse8.v per group
654	  //     base (v0/v8/v16/v24) covers 8 registers, landing in any progbuf slot of
655	  //     the single grouped Program-Buffer execution.
656	  std::vector<int> missing;
657	  std::optional<std::size_t> first_vse_idx;
658	  for (uint16_t g = 0; g < 32; g += 8) {
659	    const uint32_t want = hybrid::encode_vse8_v(static_cast<uint8_t>(g), 7);
660	    std::optional<std::size_t> at;
661	    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
662	      const auto& op = bus.ops[i];
663	      if (op.kind == DmiOp::Kind::Write
664	          && op.reg >= hybrid::kProgbuf0
665	          && op.reg <= hybrid::kProgbuf0 + hybrid::kProgbufMaxInsns
666	          && op.value == want) { at = i; break; }
667	    }
668	    if (!at) { missing.push_back(g); continue; }
669	    if (!first_vse_idx || *at < *first_vse_idx) first_vse_idx = at;
670	  }
671	  CHECK(missing.empty());
672	  REQUIRE(first_vse_idx.has_value());
673	
674	  // (b) the dump sweep runs AFTER the mcycle/minstret reads, so the sweep's
675	  //     vse8.v insns (and any counter increments) cannot corrupt the drained
676	  //     counters. minstret(0xB02) is the last counter read before the sweep.
677	  std::optional<std::size_t> minstret_read_idx;
678	  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
679	    const auto& op = bus.ops[i];
680	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
681	    const auto regno   = static_cast<uint16_t>(op.value & 0xFFFFu);
682	    const bool is_read = ((op.value >> 16) & 1u) == 0u;
683	    if (is_read && regno == hybrid::regno_csr(0xB02)) minstret_read_idx = i;
684	  }
685	  REQUIRE(minstret_read_idx.has_value());
686	  CHECK(*minstret_read_idx < *first_vse_idx);
687	}
